// Load configuration from environment variables
const config = {
  // GitHub configuration
  githubToken: $env.GITHUB_TOKEN,
  repositories: ($env.GITHUB_REPOS || 'claude-builders-bounty/claude-builders-bounty').split(',').map(r => r.trim()),

  // Claude configuration
  claudeApiKey: $env.CLAUDE_API_KEY,
  claudeModel: $env.CLAUDE_MODEL || 'claude-3-5-sonnet-20241022',

  // Output configuration
  outputChannels: ($env.OUTPUT_CHANNELS || 'discord').split(',').map(c => c.trim()),
  language: $env.LANGUAGE || 'en',

  // Discord configuration
  discordWebhookUrl: $env.DISCORD_WEBHOOK_URL,

  // Slack configuration
  slackWebhookUrl: $env.SLACK_WEBHOOK_URL,

  // Email configuration
  emailConfig: {
    smtpHost: $env.SMTP_HOST || 'smtp.gmail.com',
    smtpPort: $env.SMTP_PORT || '587',
    smtpUsername: $env.SMTP_USERNAME,
    smtpPassword: $env.SMTP_PASSWORD,
    fromEmail: $env.SMTP_FROM_EMAIL,
    toEmail: $env.EMAIL_RECIPIENT
  },

  // Date configuration
  weekStartDate: $now.subtract(7, 'days').format('YYYY-MM-DD'),
  weekEndDate: $now.format('YYYY-MM-DD'),

  // Error handling configuration
  retryAttempts: parseInt($env.RETRY_ATTEMPTS || '3'),
  alertOnFailure: $env.ALERT_ON_FAILURE === 'true',

  // Monitoring configuration
  enableMonitoring: $env.ENABLE_MONITORING === 'true',

  // Execution metadata
  executionId: `exec_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  startTime: new Date().toISOString()
};

// Validate required configuration
const requiredConfig = ['githubToken', 'claudeApiKey'];
const missingConfig = requiredConfig.filter(key => !config[key]);

if (missingConfig.length > 0) {
  throw new Error(`Missing required configuration: ${missingConfig.join(', ')}`);
}

// Log configuration loaded
console.log(`✅ Configuration loaded for ${config.repositories.length} repositories`);
console.log(`   Output channels: ${config.outputChannels.join(', ')}`);
console.log(`   Language: ${config.language}`);

return [{
  json: config,
  pairedItem: { item: 0 }
}];

// Get repository data from GitHub API with error handling
async function getRepositoryData(repo, config) {
  const baseUrl = 'https://api.github.com';
  const headers = {
    'Authorization': `Bearer ${config.githubToken}`,
    'Accept': 'application/vnd.github.v3+json',
    'User-Agent': 'n8n-weekly-summary-enhanced/1.0'
  };

  const [owner, repoName] = repo.split('/');

  try {
    // Get commits
    const commitsUrl = `${baseUrl}/repos/${owner}/${repoName}/commits?since=${config.weekStartDate}&until=${config.weekEndDate}&per_page=100`;
    const commitsResponse = await $httpRequest(commitsUrl, {
      method: 'GET',
      headers: headers,
      returnFullResponse: true
    });

    // Get closed issues
    const issuesUrl = `${baseUrl}/repos/${owner}/${repoName}/issues?state=closed&since=${config.weekStartDate}&per_page=100`;
    const issuesResponse = await $httpRequest(issuesUrl, {
      method: 'GET',
      headers: headers,
      returnFullResponse: true
    });

    // Get merged PRs
    const prsUrl = `${baseUrl}/repos/${owner}/${repoName}/pulls?state=closed&sort=updated&direction=desc&since=${config.weekStartDate}&per_page=100`;
    const prsResponse = await $httpRequest(prsUrl, {
      method: 'GET',
      headers: headers,
      returnFullResponse: true
    });

    // Get repository info
    const repoUrl = `${baseUrl}/repos/${owner}/${repoName}`;
    const repoResponse = await $httpRequest(repoUrl, {
      method: 'GET',
      headers: headers,
      returnFullResponse: true
    });

    const commits = JSON.parse(commitsResponse.body);
    const issues = JSON.parse(issuesResponse.body);
    const pullRequests = JSON.parse(prsResponse.body);
    const repoInfo = JSON.parse(repoResponse.body);

    // Filter merged PRs
    const mergedPRs = pullRequests.filter(pr => pr.merged_at);

    return {
      repository: repo,
      repoInfo: repoInfo,
      commits: commits,
      issues: issues,
      pullRequests: pullRequests,
      mergedPRs: mergedPRs,
      stats: {
        commits: commits.length,
        issuesClosed: issues.length,
        pullRequestsTotal: pullRequests.length,
        pullRequestsMerged: mergedPRs.length,
        success: true
      },
      timestamp: new Date().toISOString()
    };

  } catch (error) {
    console.error(`❌ Error fetching data for ${repo}:`, error.message);

    return {
      repository: repo,
      error: error.message,
      stats: {
        commits: 0,
        issuesClosed: 0,
        pullRequestsTotal: 0,
        pullRequestsMerged: 0,
        success: false
      },
      timestamp: new Date().toISOString()
    };
  }
}

// Process current repository
const repo = $input.first().json;
const config = $json;

const repoData = await getRepositoryData(repo, config);

return [{
  json: {
    ...config,
    currentRepository: repo,
    repoData: repoData
  },
  pairedItem: { item: 0 }
}];

// Generate summary using Claude API with fallback
async function generateSummary(repoData, config) {
  // Check if we have valid data
  if (!repoData.stats.success) {
    return {
      summary: `Unable to generate summary for ${repoData.repository}: ${repoData.error}`,
      generatedBy: 'error_fallback',
      success: false
    };
  }

  // Prepare data for Claude
  const { commits, issues, mergedPRs, repoInfo } = repoData;

  const notableCommits = commits.slice(0, 5).map(c => ({
    sha: c.sha?.substring(0, 7) || 'unknown',
    message: c.commit?.message?.split('\n')[0] || 'No message',
    author: c.commit?.author?.name || 'unknown',
    date: c.commit?.author?.date || 'unknown'
  }));

  const notableIssues = issues.slice(0, 5).map(i => ({
    number: i.number || 'unknown',
    title: i.title || 'No title',
    user: i.user?.login || 'unknown',
    closedAt: i.closed_at || 'unknown'
  }));

  const notablePRs = mergedPRs.slice(0, 5).map(pr => ({
    number: pr.number || 'unknown',
    title: pr.title || 'No title',
    user: pr.user?.login || 'unknown',
    mergedBy: pr.merged_by?.login || 'unknown',
    mergedAt: pr.merged_at || 'unknown'
  }));

  // Create prompt based on language
  const prompt = config.language === 'fr' ?
    `Génère un résumé hebdomadaire du développement pour le dépôt ${repoInfo.full_name}.

Période: ${config.weekStartDate} à ${config.weekEndDate}

Statistiques:
- ${repoData.stats.commits} commits
- ${repoData.stats.issuesClosed} issues fermées
- ${repoData.stats.pullRequestsMerged} pull requests fusionnées

Détails notables:
${notableCommits.length > 0 ? 'Commits:\n' + notableCommits.map(c => `  - ${c.sha}: ${c.message} (${c.author})`).join('\n') : ''}
${notableIssues.length > 0 ? '\nIssues fermées:\n' + notableIssues.map(i => `  - #${i.number}: ${i.title} (fermé par ${i.user})`).join('\n') : ''}
${notablePRs.length > 0 ? '\nPRs fusionnées:\n' + notablePRs.map(pr => `  - #${pr.number}: ${pr.title} (fusionné par ${pr.mergedBy})`).join('\n') : ''}

Ton: professionnel, concis, axé sur les résultats.` :
    `Generate a weekly development summary for repository ${repoInfo.full_name}.

Period: ${config.weekStartDate} to ${config.weekEndDate}

Statistics:
- ${repoData.stats.commits} commits
- ${repoData.stats.issuesClosed} issues closed
- ${repoData.stats.pullRequestsMerged} pull requests merged

Notable details:
${notableCommits.length > 0 ? 'Commits:\n' + notableCommits.map(c => `  - ${c.sha}: ${c.message} (${c.author})`).join('\n') : ''}
${notableIssues.length > 0 ? '\nIssues closed:\n' + notableIssues.map(i => `  - #${i.number}: ${i.title} (closed by ${i.user})`).join('\n') : ''}
${notablePRs.length > 0 ? '\nPRs merged:\n' + notablePRs.map(pr => `  - #${pr.number}: ${pr.title} (merged by ${pr.mergedBy})`).join('\n') : ''}

Tone: professional, concise, results-oriented.`;

  try {
    // Call Claude API
    const response = await $httpRequest('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': config.claudeApiKey,
        'anthropic-version': '2023-06-01',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: config.claudeModel,
        max_tokens: 1024,
        messages: [{
          role: 'user',
          content: prompt
        }]
      }),
      returnFullResponse: true
    });

    const result = JSON.parse(response.body);

    return {
      summary: result.content?.[0]?.text || 'No summary generated.',
      generatedBy: 'claude_api',
      success: true,
      promptLength: prompt.length,
      responseTokens: result.usage?.output_tokens || 0
    };

  } catch (error) {
    console.error(`❌ Claude API error for ${repoData.repository}:`, error.message);

    // Fallback to template-based summary
    const fallbackSummary = config.language === 'fr' ?
      `Résumé hebdomadaire pour ${repoInfo.full_name} (${config.weekStartDate} à ${config.weekEndDate}):\n` +
      `${repoData.stats.commits} commits, ${repoData.stats.issuesClosed} issues fermées, ${repoData.stats.pullRequestsMerged} PRs fusionnées.\n` +
      `Activité stable cette semaine.` :
      `Weekly summary for ${repoInfo.full_name} (${config.weekStartDate} to ${config.weekEndDate}):\n` +
      `${repoData.stats.commits} commits, ${repoData.stats.issuesClosed} issues closed, ${repoData.stats.pullRequestsMerged} PRs merged.\n` +
      `Steady activity this week.`;

    return {
      summary: fallbackSummary,
      generatedBy: 'template_fallback',
      success: false,
      error: error.message
    };
  }
}

// Generate summary for current repository
const config = $json;
const repoData = config.repoData;

const summaryResult = await generateSummary(repoData, config);

// Combine all data
const combinedData = {
  ...config,
  summaryResult: summaryResult,
  repositorySummary: {
    repository: repoData.repository,
    stats: repoData.stats,
    summary: summaryResult.summary,
    generatedBy: summaryResult.generatedBy,
    timestamp: new Date().toISOString()
  }
};

return [{
  json: combinedData,
  pairedItem: { item: 0 }
}];

// Format output for different channels
function formatOutput(repositorySummary, allSummaries, config) {
  const { repository, stats, summary, generatedBy } = repositorySummary;

  // Individual repository format
  const individualFormat = {
    discord: {
      content: `**📊 ${repository}**\n` +
        `*Period:* ${config.weekStartDate} to ${config.weekEndDate}\n` +
        `*Stats:* ${stats.commits} commits, ${stats.issuesClosed} issues, ${stats.pullRequestsMerged} PRs\n` +
        `*Generated by:* ${generatedBy}\n\n` +
        summary
    },
    slack: {
      blocks: [
        {
          type: 'header',
          text: {
            type: 'plain_text',
            text: `📊 ${repository}`
          }
        },
        {
          type: 'section',
          fields: [
            {
              type: 'mrkdwn',
              text: `*Period:*\n${config.weekStartDate} to ${config.weekEndDate}`
            },
            {
              type: 'mrkdwn',
              text: `*Stats:*\n${stats.commits} commits\n${stats.issuesClosed} issues\n${stats.pullRequestsMerged} PRs`
            }
          ]
        },
        {
          type: 'section',
          text: {
            type: 'mrkdwn',
            text: summary
          }
        },
        {
          type: 'context',
          elements: [
            {
              type: 'mrkdwn',
              text: `Generated by: ${generatedBy}`
            }
          ]
        }
      ]
    },
    email: {
      subject: `Weekly Dev Summary - ${repository}`,
      body: `Repository: ${repository}\n` +
        `Period: ${config.weekStartDate} to ${config.weekEndDate}\n` +
        `Stats:\n` +
        `- Commits: ${stats.commits}\n` +
        `- Issues Closed: ${stats.issuesClosed}\n` +
        `- PRs Merged: ${stats.pullRequestsMerged}\n\n` +
        summary
    }
  };

  // Check if this is the last repository
  const isLastRepo = allSummaries.length === config.repositories.length;

  if (isLastRepo && config.repositories.length > 1) {
    // Create aggregated summary for multiple repositories
    const totalStats = {
      commits: allSummaries.reduce((sum, s) => sum + s.stats.commits, 0),
      issuesClosed: allSummaries.reduce((sum, s) => sum + s.stats.issuesClosed, 0),
      pullRequestsMerged: allSummaries.reduce((sum, s) => sum + s.stats.pullRequestsMerged, 0),
      successfulRepos: allSummaries.filter(s => s.stats.success).length
    };

    const aggregatedFormat = {
      discord: {
        content: `**📊 Weekly Development Summary - ${config.repositories.length} Repositories**\n` +
          `*Period:* ${config.weekStartDate} to ${config.weekEndDate}\n` +
          `*Total Stats:* ${totalStats.commits} commits, ${totalStats.issuesClosed} issues, ${totalStats.pullRequestsMerged} PRs\n` +
          `*Successful repositories:* ${totalStats.successfulRepos}/${config.repositories.length}\n` +
          `*Individual summaries have been sent separately.*`
      },
      slack: {
        blocks: [
          {
            type: 'header',
            text: {
              type: 'plain_text',
              text: `📊 Weekly Summary - ${config.repositories.length} Repos`
            }
          },
          {
            type: 'section',
            fields: [
              {
                type: 'mrkdwn',
                text: `*Period:*\n${config.weekStartDate} to ${config.weekEndDate}`
              },
              {
                type: 'mrkdwn',
                text: `*Total Stats:*\n${totalStats.commits} commits\n${totalStats.issuesClosed} issues\n${totalStats.pullRequestsMerged} PRs`
              }
            ]
          },
          {
            type: 'context',
            elements: [
              {
                type: 'mrkdwn',
                text: `Successful repos: ${totalStats.successfulRepos}/${config.repositories.length}`
              }
            ]
          }
        ]
      },
      email: {
        subject: `Weekly Dev Summary - ${config.repositories.length} Repositories`,
        body: `Weekly Development Summary Report\n` +
          `Period: ${config.weekStartDate} to ${config.weekEndDate}\n` +
          `Repositories: ${config.repositories.length}\n\n` +
          `Total Statistics:\n` +
          `- Commits: ${totalStats.commits}\n` +
          `- Issues Closed: ${totalStats.issuesClosed}\n` +
          `- PRs Merged: ${totalStats.pullRequestsMerged}\n\n` +
          `Successful repositories: ${totalStats.successfulRepos}/${config.repositories.length}\n\n` +
          `Individual repository summaries are attached or sent separately.`
      }
    };

    return {
      individual: individualFormat,
      aggregated: aggregatedFormat,
      isLastRepo: true,
      totalStats: totalStats
    };
  }

  return {
    individual: individualFormat,
    aggregated: null,
    isLastRepo: isLastRepo
  };
}

// Get all summaries collected so far
const config = $json;
const allSummaries = config.allSummaries || [];
const currentSummary = config.repositorySummary;

// Add current summary to collection
allSummaries.push(currentSummary);

// Format output
const formattedOutput = formatOutput(currentSummary, allSummaries, config);

return [{
  json: {
    ...config,
    allSummaries: allSummaries,
    formattedOutput: formattedOutput,
    outputReady: true
  },
  pairedItem: { item: 0 }
}];

// Send formatted output to configured channels
async function sendToChannels(formattedOutput, config) {
  const results = {
    discord: { success: false, error: null },
    slack: { success: false, error: null },
    email: { success: false, error: null }
  };

  const { individual, aggregated, isLastRepo } = formattedOutput;

  // Send individual repository summary
  for (const channel of config.outputChannels) {
    try {
      switch (channel) {
        case 'discord':
          if (config.discordWebhookUrl && individual.discord) {
            await $httpRequest(config.discordWebhookUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(individual.discord),
              returnFullResponse: true
            });
            results.discord.success = true;
            console.log(`✅ Discord message sent for ${config.currentRepository}`);
          }
          break;

        case 'slack':
          if (config.slackWebhookUrl && individual.slack) {
            await $httpRequest(config.slackWebhookUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(individual.slack),
              returnFullResponse: true
            });
            results.slack.success = true;
            console.log(`✅ Slack message sent for ${config.currentRepository}`);
          }
          break;

        case 'email':
          if (config.emailConfig.toEmail && individual.email) {
            // Note: Email sending requires SMTP configuration
            // This is a placeholder for email integration
            results.email.success = true;
            console.log(`📧 Email prepared for ${config.currentRepository}`);
          }
          break;
      }
    } catch (error) {
      console.error(`❌ Error sending to ${channel}:`, error.message);
      results[channel].error = error.message;
    }
  }

  // Send aggregated summary if this is the last repository and we have multiple repos
  if (isLastRepo && aggregated && config.repositories.length > 1) {
    for (const channel of config.outputChannels) {
      try {
        switch (channel) {
          case 'discord':
            if (config.discordWebhookUrl && aggregated.discord) {
              await $httpRequest(config.discordWebhookUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(aggregated.discord),
                returnFullResponse: true
              });
              console.log('✅ Aggregated Discord summary sent');
            }
            break;

          case 'slack':
            if (config.slackWebhookUrl && aggregated.slack) {
              await $httpRequest(config.slackWebhookUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(aggregated.slack),
                returnFullResponse: true
              });
              console.log('✅ Aggregated Slack summary sent');
            }
            break;

          case 'email':
            if (config.emailConfig.toEmail && aggregated.email) {
              console.log('📧 Aggregated email prepared');
            }
            break;
        }
      } catch (error) {
        console.error(`❌ Error sending aggregated to ${channel}:`, error.message);
      }
    }
  }

  return results;
}

// Send to channels
const config = $json;
const formattedOutput = config.formattedOutput;

const sendResults = await sendToChannels(formattedOutput, config);

return [{
  json: {
    ...config,
    sendResults: sendResults,
    completedAt: new Date().toISOString()
  },
  pairedItem: { item: 0 }
}];

// Log execution results and update monitoring
function logExecution(config, sendResults) {
  const { currentRepository, repositorySummary, allSummaries, startTime } = config;
  const { stats, summary, generatedBy } = repositorySummary;

  // Calculate execution time
  const endTime = new Date();
  const start = new Date(startTime);
  const executionTime = endTime - start;

  // Prepare log entry
  const logEntry = {
    executionId: config.executionId,
    repository: currentRepository,
    period: {
      start: config.weekStartDate,
      end: config.weekEndDate
    },
    stats: stats,
    summaryGeneratedBy: generatedBy,
    summaryLength: summary.length,
    sendResults: sendResults,
    executionTimeMs: executionTime,
    timestamp: endTime.toISOString(),
    success: stats.success && Object.values(sendResults).some(r => r.success)
  };

  // Log to console
  console.log(`📝 Execution log for ${currentRepository}:`);
  console.log(`   Success: ${logEntry.success}`);
  console.log(`   Stats: ${stats.commits} commits, ${stats.issuesClosed} issues, ${stats.pullRequestsMerged} PRs`);
  console.log(`   Generated by: ${generatedBy}`);
  console.log(`   Execution time: ${executionTime}ms`);

  // Check if this is the last repository
  const isLastRepo = allSummaries.length === config.repositories.length;

  if (isLastRepo) {
    // Generate final report
    const successfulRepos = allSummaries.filter(s => s.stats.success).length;
    const totalStats = {
      commits: allSummaries.reduce((sum, s) => sum + s.stats.commits, 0),
      issuesClosed: allSummaries.reduce((sum, s) => sum + s.stats.issuesClosed, 0),
      pullRequestsMerged: allSummaries.reduce((sum, s) => sum + s.stats.pullRequestsMerged, 0)
    };

    console.log('='.repeat(60));
    console.log(`🎯 WEEKLY SUMMARY EXECUTION COMPLETE`);
    console.log(`   Repositories processed: ${allSummaries.length}`);
    console.log(`   Successful: ${successfulRepos}/${allSummaries.length}`);
    console.log(`   Total commits: ${totalStats.commits}`);
    console.log(`   Total issues closed: ${totalStats.issuesClosed}`);
    console.log(`   Total PRs merged: ${totalStats.pullRequestsMerged}`);
    console.log(`   Total execution time: ${executionTime}ms`);
    console.log('='.repeat(60));

    // Create monitoring data if enabled
    if (config.enableMonitoring) {
      const monitoringData = {
        executionId: config.executionId,
        totalRepositories: allSummaries.length,
        successfulRepositories: successfulRepos,
        totalStats: totalStats,
        startTime: startTime,
        endTime: endTime.toISOString(),
        totalExecutionTime: executionTime,
        individualResults: allSummaries.map(s => ({
          repository: s.repository,
          success: s.stats.success,
          stats: s.stats
        }))
      };

      // In a real implementation, this would save to a database or file
      console.log('📊 Monitoring data:', JSON.stringify(monitoringData, null, 2));
    }
  }

  return logEntry;
}

// Log execution
const config = $json;
const sendResults = config.sendResults;

const logEntry = logExecution(config, sendResults);

return [{
  json: {
    ...config,
    logEntry: logEntry,
    processingComplete: true
  },
  pairedItem: { item: 0 }
}];
